<script setup lang="ts">import {computed} from 'vue';import type {CoverageResult} from '../types/entities';import {percent,number} from '../utils/format';const props=defineProps<{result:CoverageResult}>();const cap=computed(()=>props.result.mode==='capacity')</script><template><div class="coverage-summary"><div><small>{{cap?'已服务需求权重':'加权需求覆盖'}}</small><strong>{{percent(result.coverage_rate)}}</strong><span>{{result.covered_weight}} / {{result.total_weight}} 需求权重</span></div><div><small>选址成本</small><strong>{{number(result.spent)}}<em>万元</em></strong><span>预算 {{result.budget}} 万元 · {{result.selected_ids.length}} 个点位</span></div><div><small>{{cap?'仍未服务':'仍未覆盖'}}</small><strong>{{result.uncovered_points}}<em>处</em></strong><span>{{cap?'容量推演 · ':''}}覆盖半径 {{result.radius_km}} km</span></div></div></template>
